// Skyworks - The Backrooms blocks (dimension skyworks:backrooms, see tools/gen_backrooms.py).
//
// Unbreakable on purpose: the Backrooms are escaped by dying, not by digging (players are in Adventure there, but
// explosions, cannons and spells don't care about game modes). Textures/models/blockstates live in
// kubejs/assets/kubejs and are generated by tools/gen_backrooms.py. The fluorescent panels give light 15; the dead
// ones give none. Mobs can never spawn on them (the dweller is spawned by its own mod, not by spawn rules).

StartupEvents.registry('block', event => {
  const SoundType = Java.loadClass('net.minecraft.world.level.block.SoundType')
  const MapColor = Java.loadClass('net.minecraft.world.level.material.MapColor')
  const block = (id, name, sound, color, light) => {
    const b = event.create('backrooms_' + id)
      .displayName(name)
      .soundType(sound)
      .mapColor(color)
      .unbreakable()
      .resistance(3600000)
      .noDrops()
      .noValidSpawns(true)
    if (light) b.lightLevel(light)
    return b
  }
  block('wallpaper', 'Backrooms Wallpaper', SoundType.WOOD, MapColor.SAND)
  block('wallpaper_stained', 'Stained Backrooms Wallpaper', SoundType.WOOD, MapColor.SAND)
  block('wallpaper_trim', 'Backrooms Wallpaper Baseboard', SoundType.WOOD, MapColor.SAND)
  block('carpet', 'Moist Carpet', SoundType.WOOL, MapColor.TERRACOTTA_YELLOW)
  block('carpet_damp', 'Damp Carpet', SoundType.WOOL, MapColor.TERRACOTTA_YELLOW)
  block('ceiling', 'Ceiling Tile', SoundType.STONE, MapColor.TERRACOTTA_WHITE)
  block('ceiling_stained', 'Stained Ceiling Tile', SoundType.STONE, MapColor.TERRACOTTA_WHITE)
  block('light', 'Fluorescent Panel', SoundType.GLASS, MapColor.SNOW, 1.0)
  block('light_dead', 'Dead Fluorescent Panel', SoundType.GLASS, MapColor.COLOR_LIGHT_GRAY)
})
